import bpy,bmesh,json,sys
from mathutils import Vector
R=Path(__file__).resolve().parents[2];B=R/'12_Blender_Model';sys.path.insert(0,str(B/'scripts'));from roof_panel_math import inset
base='MUDAM_R85_BATI_UST_SAHANLIK_KABUK_v001.blend';out=B/'scenes/MUDAM_R86_PAVYON_CAM_KENAR_KAPANISI_v001.blend';assert not out.exists();bpy.ops.wm.open_mainfile(filepath=str(B/'scenes'/base));P=json.loads((B/'reports/R13_build_report.json').read_text());cfg=json.loads((B/'config/pavilion_glazing.json').read_text());changed=[];checks=[]
