 ob=bpy.data.objects[pane['name']];ps=[Vector(p) for p in pane['source_polygon']];n=Vector(pane['normal']);a=ps[0];u=(ps[1]-a).normalized();v=n.cross(u).normalized();poly=[[(p-a).dot(u),(p-a).dot(v)] for p in ps];trim=inset(poly,.012);assert len(trim)>=3;new=[a+u*x+v*y for x,y in trim];N=len(new);me=bpy.data.meshes.new(ob.name+'_metric_inset');inv=ob.matrix_world.inverted();me.from_pydata([tuple(inv@p) for p in new]+[tuple(inv@(p-n*cfg['glass_thickness_m'])) for p in new],[],[tuple(range(N-1,-1,-1)),tuple(range(N,2*N))]+[(i,(i+1)%N,(i+1)%N+N,i+N) for i in range(N)]);me.update();bm=bmesh.new();bm.from_mesh(me);bmesh.ops.recalc_face_normals(bm,faces=list(bm.faces));bm.to_mesh(me);bm.free()
 for mat in ob.data.materials:me.materials.append(mat)
 ob.data=me;ob['edge_closure_revision']='R86 constant12mm inset inside existing frame centerlines; previous centroid shrink created aspect-dependent holes';changed.append(ob.name);checks.append(dict(name=ob.name,source_polygon=pane['source_polygon'],normal=pane['normal'],inset_m=.012))
